const BASE = "https://api.upstream.example";

export async function call(path, body, fetchImpl = fetch) {
  const response = await fetchImpl(`${BASE}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`upstream ${response.status} on ${path}`);
  }

  return response.json();
}

import { DEFAULT_TARGET, TARGETS } from "./targets.js";

const STEPS = ["build", "upload", "activate"];

export function deploy(args, log = console.log, targets = TARGETS) {
  const dryRun = args.includes("--dry-run");
  const target = resolveTarget(args, targets);

  for (const step of STEPS) {
    log(`-> ${step}`);
    if (!dryRun) {
      target[step]();
    }
  }

  log(dryRun ? "dry run: 3 steps skipped" : "deployed: 3 steps");
}

function resolveTarget(args, targets) {
  const i = args.indexOf("--target");
  const name = i === -1 ? DEFAULT_TARGET : args[i + 1];
  const target = Object.hasOwn(targets, name) ? targets[name] : undefined;
  if (!target) {
    throw new Error(`unknown target: ${name}`);
  }
  for (const step of STEPS) {
    if (typeof target[step] !== "function") {
      throw new Error(`target ${name} has no ${step} step`);
    }
  }
  return target;
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { deploy } from "../src/cli/deploy.js";

function capture() {
  const lines = [];
  return { lines, log: (line) => lines.push(line) };
}

test("dry run skips the steps and says so", async () => {
  const { lines, log } = capture();
  await deploy(["--dry-run"], log);
  assert.equal(lines.at(-1), "dry run: 3 steps skipped");
});

test("a full deploy reports every step", async () => {
  const { lines, log } = capture();
  await deploy([], log);
  assert.deepEqual(lines, ["-> build", "-> upload", "-> activate", "deployed: 3 steps"]);
});

function recordingTarget() {
  const calls = [];
  return {
    calls,
    build: () => calls.push("build"),
    upload: () => calls.push("upload"),
    activate: () => calls.push("activate"),
  };
}

test("deploy runs the three steps against the target it is given", async () => {
  const { log } = capture();
  const target = recordingTarget();
  await deploy([], log, target);
  assert.deepEqual(target.calls, ["build", "upload", "activate"]);
});

test("dry run never touches the target", async () => {
  const { log } = capture();
  const target = recordingTarget();
  await deploy(["--dry-run"], log, target);
  assert.deepEqual(target.calls, []);
});

test("async steps run in order and finish before success is reported", async () => {
  const lines = [];
  const step = (name) => async () => {
    await new Promise((resolve) => setTimeout(resolve, 5));
    lines.push(`done ${name}`);
  };
  const target = { build: step("build"), upload: step("upload"), activate: step("activate") };
  await deploy([], (line) => lines.push(line), target);
  assert.deepEqual(lines, [
    "-> build", "done build",
    "-> upload", "done upload",
    "-> activate", "done activate",
    "deployed: 3 steps",
  ]);
});

test("a failing step stops the deploy and rejects", async () => {
  const { lines, log } = capture();
  const target = recordingTarget();
  target.upload = async () => { throw new Error("s3 down"); };
  await assert.rejects(deploy([], log, target), /s3 down/);
  assert.deepEqual(target.calls, ["build"]);
  assert.ok(!lines.includes("deployed: 3 steps"));
});

test("a target missing a step is rejected before anything runs", async () => {
  const { log } = capture();
  const target = recordingTarget();
  delete target.activate;
  await assert.rejects(deploy([], log, target), /target missing step: activate/);
  assert.deepEqual(target.calls, []);
});

